from solution import tn_ap


def test_issue_example_given():
    """Example assert tn_ap(1,5,2)==9."""
    assert tn_ap(1, 5, 2) == 9  # 1+(5-1)*2=1+8=9


def test_issue_first_term_equals_a():
    """Boundary n=1 returns first term a."""
    assert tn_ap(5, 1, 3) == 5  # 5+(1-1)*3=5+0=5


def test_issue_second_term_equals_a_plus_d():
    """Just above boundary n=2 returns a+d."""
    assert tn_ap(2, 2, 3) == 5  # 2+(2-1)*3=2+3=5


def test_issue_zero_difference_constant():
    """Zero difference keeps progression constant at a."""
    assert tn_ap(7, 10, 0) == 7  # 7+(10-1)*0=7+0=7


def test_issue_negative_difference():
    """Negative difference decreases arithmetic progression."""
    assert tn_ap(10, 4, -2) == 4  # 10+(4-1)*(-2)=10-6=4


def test_issue_zero_first_term():
    """Zero first term follows a+(n-1)*d."""
    assert tn_ap(0, 6, 4) == 20  # 0+(6-1)*4=0+20=20


def test_issue_negative_first_term():
    """Negative first term follows a+(n-1)*d."""
    assert tn_ap(-3, 4, 5) == 12  # -3+(4-1)*5=-3+15=12


def test_contract_general_formula():
    """Documented rule: n-th term is a+(n-1)*d."""
    assert tn_ap(3, 4, 5) == 18  # 3+(4-1)*5=3+15=18


def test_contract_large_n():
    """Documented rule: n-th term is a+(n-1)*d for large n."""
    assert tn_ap(1, 100, 1) == 100  # 1+(100-1)*1=1+99=100


def test_contract_argument_order():
    """Public interface tn_ap(a, n, d) keeps a first and d last."""
    assert tn_ap(4, 3, 2) == 8  # 4+(3-1)*2=4+4=8
